import pandas as pd, numpy as np, glob, os
# 5m bars, closed-bar features only; signal on bar t is tradable at open of t+1
SYMS=sorted(os.listdir('/dataset/discovery/bars_5m'))
COLS=['ts_ms','quote_volume','signed_usd','close']
def zs(x,w):
    m=x.rolling(w,min_periods=w//2).mean(); s=x.rolling(w,min_periods=w//2).std()
    return (x-m)/s.replace(0,np.nan)
res={}
for sym in SYMS:
    d=pd.concat([pd.read_parquet(f,columns=COLS) for f in sorted(glob.glob(f'/dataset/discovery/bars_5m/{sym}/*.parquet'))],ignore_index=True)
    d=d.sort_values('ts_ms').drop_duplicates('ts_ms').reset_index(drop=True)
    d['ret']=np.log(d.close/d.close.shift(1)); d['ret']=d['ret'].where(d['ret'].abs()<0.5)
    fz=zs(d.signed_usd.astype(float)/d.quote_volume.astype(float),288)
    rz=zs(d.ret.abs(),288)
    sig={'fz':fz,'abs':fz/(1+rz.clip(lower=0)),'thin':fz*rz.clip(lower=0)}
    yr=pd.to_datetime(d.ts_ms,unit='ms').dt.year
    for h in (48,96,288):
        fwd=np.log(d.close.shift(-h)/d.close)
        for k,v in sig.items():
            g=pd.DataFrame({'s':v,'f':fwd,'y':yr}).dropna()
            for y,gg in g.groupby('y'):
                if len(gg)<500: continue
                res.setdefault((k,h),{}).setdefault(y,[]).append(gg.s.corr(gg.f))
for k in sorted(res):
    print(k, {y:round(float(np.nanmean(v)),4) for y,v in sorted(res[k].items())})
# Observed: all |IC|<=0.014 at h=48 (4h), <=0.005 at h=288 (24h), mostly negative.
# Gross edge ~ IC * sigma_4h (~0.3-0.6%) = 2-3 bps << 14-19 bps round trip.

import numpy as np, pandas as pd, glob
D='/dataset/discovery'
COLS=['ts_ms','quote_volume','buy_usd','sell_usd','n_agg','n_raw','large_buy_usd','large_sell_usd','xlarge_buy_usd','xlarge_sell_usd','n_large','close','max_trade_usd']
def load(s):
    d=pd.concat([pd.read_parquet(f,columns=COLS) for f in sorted(glob.glob(f'{D}/bars_5m/{s}/*.parquet'))],ignore_index=True)
    return d.sort_values('ts_ms').reset_index(drop=True)
def fundcum(d,s):
    fs=sorted(glob.glob(f'{D}/funding/{s}/*.parquet')); out=np.zeros(len(d))
    if not fs: return out
    f=pd.concat([pd.read_parquet(x) for x in fs],ignore_index=True).sort_values('ts_ms')
    idx=np.searchsorted(d.ts_ms.values,f.ts_ms.values,side='left'); ok=idx<len(d)
    c=np.zeros(len(d)+1); np.add.at(c,idx[ok],f.rate.values[ok].astype(float))
    return np.cumsum(c[:len(d)])
def ztrail(x,win=288):
    s=pd.Series(x); m=s.rolling(win,min_periods=72).mean().shift(1); sd=s.rolling(win,min_periods=72).std().shift(1)
    return ((s-m)/sd.replace(0,np.nan)).values
def ev(c,fc,sig,H,cost=19.0):
    idx=np.arange(0,len(c)-H-1,H); s=sig[idx]; ok=np.isfinite(s); idx=idx[ok]; s=s[ok]
    pos=np.sign(s); lr=np.log(c[idx+H]/c[idx]); net=pos*lr-pos*(fc[idx+H]-fc[idx])-cost/1e4
    return dict(n=len(idx),net_bps=net.mean()*1e4,hit=(net>0).mean(),sharpe=net.mean()/net.std()*np.sqrt(288*365/(H*5)))
def xs_placebo(SY,H=288,cost=19.0,shuffles=200,seed=7):
    C=pd.DataFrame({s:pd.Series(load(s).close.ffill().values,index=load(s).ts_ms.values) for s in SY}).sort_index()
    M=pd.DataFrame({s:pd.Series(ztrail(load(s).max_trade_usd.values/np.maximum(load(s).quote_volume.values,1e-9)),index=load(s).ts_ms.values) for s in SY}).sort_index()
    idx=np.arange(0,len(M)-H-1,H); R=np.log(C.values[idx+H]/C.values[idx])
    def pnl(Zv):
        Zs=Zv[idx]; ok=np.isfinite(Zs).sum(1)>=6
        rk=pd.DataFrame(Zs).rank(axis=1,pct=True).values-0.5; rk=np.where(np.isfinite(Zs),rk,np.nan)
        w=-rk; w=np.where(np.isfinite(w),w,0.0); w=w/np.maximum(np.abs(w).sum(1,keepdims=True),1e-9)
        return np.nansum(w*R,axis=1)[ok]
    base=pnl(M.values); rng=np.random.default_rng(seed)
    day=(M.index.values//86_400_000); ud=np.unique(day); pl=[]
    for k in range(shuffles):
        mp=dict(zip(ud,ud[rng.permutation(len(ud))])); order=np.argsort([mp[x] for x in day],kind='stable')
        pl.append(float(pnl(M.values[order]).mean()*1e4-cost))
    pl=np.array(pl)
    return dict(base=float(base.mean()*1e4-cost),placebo_max=float(pl.max()),placebo_p95=float(np.percentile(pl,95)),placebo_mean=float(pl.mean()),placebo_sd=float(pl.std()))

